files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8a8a9a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', monospace;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 32px 28px;
  text-align: center;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
  max-width: 420px;
  width: 100%;
}

h1 {
  font-size: 1.4rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 24px;
  text-shadow: 2px 2px 0 rgba(0, 0, 0, 0.5);
}

.count {
  display: block;
  font-size: 4rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--text);
  background: var(--bg);
  border: 4px solid var(--muted);
  padding: 16px 8px;
  margin-bottom: 28px;
  line-height: 1;
  word-break: break-all;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--bg);
  background: var(--accent);
  border: 3px solid var(--accent);
  border-radius: 0;
  padding: 12px 20px;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
  box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.35);
  transition: transform 0.05s, box-shadow 0.05s, background 0.15s;
  min-width: 80px;
}

.btn:hover {
  background: #ff5c7a;
  border-color: #ff5c7a;
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 3px;
}

.btn:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .count {
    font-size: 3rem;
  }
  .btn {
    flex: 1 1 100%;
  }
}

let count = 0;

const countEl = document.getElementById('count');
const increaseBtn = document.getElementById('increase');
const decreaseBtn = document.getElementById('decrease');
const resetBtn = document.getElementById('reset');

function render() {
  countEl.textContent = String(count);
}

increaseBtn.addEventListener('click', () => {
  count += 1;
  render();
});

decreaseBtn.addEventListener('click', () => {
  count -= 1;
  render();
});

resetBtn.addEventListener('click', () => {
  count = 0;
  render();
});

render();
